// State-machine, idempotency, staleness, and execution
// contract tests for the ToolExecutionCoordinator against the fake
// workspace. Every command outcome is checked in both directions: success
// implies the workspace changed, and refusal or failure implies it did not.
// GUI-free.

#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Agent/ToolExecutionCoordinator.hpp"
#include "slic3r/GUI/JusPrin/Agent/ToolErrors.hpp"
#include "slic3r/GUI/JusPrin/Mcp/McpProtocol.hpp"
#include "../jusprin_support/FakeProductState.hpp"
#include "../jusprin_support/FakeWorkspace.hpp"

#include <nlohmann/json.hpp>

#include <filesystem>
#include <fstream>
#include <stdexcept>

using namespace Slic3r::GUI::JusPrin;
using namespace Slic3r::GUI::JusPrin::Agent;
using nlohmann::json;

namespace {

Workspace::WorkspaceSnapshot one_plate_snapshot()
{
    Workspace::WorkspaceSnapshot snapshot;
    snapshot.setup.project_name = "Coordinator Fixture";

    Workspace::WorkspacePlate plate;
    plate.id     = Workspace::PlateId(Workspace::ProjectSessionId(1), 11);
    plate.name   = "Plate 1";
    plate.active = true;

    Workspace::WorkspaceObject cube;
    cube.id   = Workspace::ObjectId(Workspace::ProjectSessionId(1), 21);
    cube.name = "cube-a";
    cube.instances.push_back({});
    plate.objects = {cube};

    snapshot.plates       = {plate};
    snapshot.active_plate = plate.id;
    return snapshot;
}

struct Harness
{
    Workspace::FakeWorkspace  workspace;
    ToolExecutionCoordinator  coordinator;
    std::vector<ToolActivity> events;
    ToolActivitySubscription  subscription;

    Harness() : workspace(one_plate_snapshot()), coordinator(workspace)
    {
        subscription = coordinator.subscribe([this](const ToolActivity& activity) { events.push_back(activity); });
    }

    Workspace::ObjectId cube_id() const { return workspace.snapshot().plates.at(0).objects.at(0).id; }

    // Every printed copy: plate_layout's quantity adds instances.
    std::size_t object_count() const
    {
        std::size_t count = 0;
        for (const Workspace::WorkspacePlate& plate : workspace.snapshot().plates)
            for (const Workspace::WorkspaceObject& object : plate.objects)
                count += object.instances.size();
        return count;
    }

    // One more copy of the cube: the canonical mutation these tests drive.
    ToolRequest duplicate_cube_request() const
    {
        ToolRequest request;
        request.tool           = "plate_layout";
        request.arguments_json = json{{"sessionId", std::to_string(workspace.snapshot().session.value())},
                                      {"objects", json::array({json{{"objectId", std::to_string(cube_id().value())},
                                                                    {"quantity", object_count() + 1}}})}}
                                     .dump();
        return request;
    }

    void pump_to_completion(const std::string& action_id, int limit = 1000)
    {
        while (!tool_state_terminal(coordinator.find(action_id)->state) && limit-- > 0)
            coordinator.pump();
    }

    std::vector<ToolState> states_of(const std::string& action_id) const
    {
        std::vector<ToolState> states;
        for (const ToolActivity& event : events)
            if (event.action_id == action_id)
                states.push_back(event.state);
        return states;
    }
};

} // namespace

TEST_CASE("project mutations are bracketed by durable version callbacks", "[tools][versions]")
{
    Harness harness;
    std::vector<std::string> boundaries;
    harness.coordinator.set_version_callbacks(
        [&boundaries](const ToolActivity& activity) {
            boundaries.push_back("before:" + activity.action_id);
            return std::string("v-before");
        },
        [&boundaries](const ToolActivity& activity, const std::string& before) {
            boundaries.push_back("after:" + before + ":" +
                                 std::string(activity.state == ToolState::Succeeded ? "succeeded" : "failed"));
        });
    harness.coordinator.set_document_boundary_callback([](const ToolActivity&) {
        FAIL("model edits must use version callbacks instead of the document-only boundary");
    });
    const std::string id = harness.coordinator.submit(harness.duplicate_cube_request(), "versioned").action_id;
    harness.pump_to_completion(id);
    CHECK(harness.coordinator.find(id)->state == ToolState::Succeeded);
    const std::vector<std::string> expected{"before:" + id, "after:v-before:succeeded"};
    CHECK(boundaries == expected);
    CHECK(harness.object_count() == 2);

    Harness refused;
    refused.coordinator.set_version_callbacks(
        [](const ToolActivity&) -> std::string { throw std::runtime_error("disk full"); },
        [](const ToolActivity&, const std::string&) { FAIL("no after-version follows a refused before-version"); });
    const std::string refused_id = refused.coordinator.submit(refused.duplicate_cube_request(), "version-refused").action_id;
    refused.pump_to_completion(refused_id);
    CHECK(refused.coordinator.find(refused_id)->state == ToolState::Failed);
    CHECK(refused.object_count() == 1);
}

TEST_CASE("Settings tools share terminal activities across adapters and return atomic results", "[tools][settings][mcp]")
{
    Harness h;
    std::vector<ToolActivity> external;
    auto sub = h.coordinator.subscribe([&](const auto& a) { if (tool_state_terminal(a.state)) external.push_back(a); });
    const auto initial = h.workspace.snapshot();
    const auto read_id = h.coordinator.submit({"settings_get", R"({"scope":"process","keys":["wall_loops","sparse_infill_density"]})"}, "read").action_id;
    h.pump_to_completion(read_id);
    REQUIRE(h.coordinator.find(read_id)->state == ToolState::Succeeded);
    const auto apply_id = h.coordinator.submit({"settings_apply_patch", json{{"scope", "process"}, {"changes", {{"wall_loops", 4}, {"sparse_infill_density", "25%"}}},
        {"expectedSessionId", std::to_string(initial.session.value())}, {"expectedRevision", initial.revision}}.dump()}, "mcp", {}, ToolSource::Mcp).action_id;
    h.pump_to_completion(apply_id);
    const auto activity = *h.coordinator.find(apply_id);
    REQUIRE(activity.state == ToolState::Succeeded);
    const auto result = json::parse(activity.result_json);
    REQUIRE(result["applied"] == true);
    REQUIRE(result["changes"].size() == 2);
    REQUIRE(result["projectUndo"] == false);
    REQUIRE(result["presetDirty"] == true);
    REQUIRE(result["scope"] == "process");
    REQUIRE(result["presetName"] == "Fixture process");
    REQUIRE(result["savedAs"] == "");
    REQUIRE(result["revision"] == initial.revision + 1);
    REQUIRE(external.back().result_json == h.events.back().result_json);
    REQUIRE(Mcp::activity_result(activity, h.workspace.snapshot())["structuredContent"] == result);
}
    harness.coordinator.forget_terminal_activities({"chat-message"});
    CHECK(harness.coordinator.find(first) == nullptr);
    REQUIRE(harness.coordinator.find(other));
    CHECK(harness.coordinator.find(other)->state == ToolState::Running);
}

TEST_CASE("the purpose and plan are recorded without moving the revision", "[tools][intent][plan]")
{
    Harness h;
    FakeProductState store;
    h.coordinator.set_product_state(&store);
    h.coordinator.set_version_callbacks(
        [](const ToolActivity&) -> std::string {
            FAIL("document-only actions must not pin a model checkpoint");
            return {};
        },
        [](const ToolActivity&, const std::string&) {
            FAIL("document-only actions must not record a model-version operation");
        });
    std::vector<std::string> document_boundaries;
    h.coordinator.set_document_boundary_callback([&document_boundaries](const ToolActivity& activity) {
        document_boundaries.push_back(activity.action_id);
    });
    const auto& registry = ToolRegistry::instance();

    auto call = [&h](const char* tool, json arguments) -> const ToolActivity& {
        return h.coordinator.submit({tool, arguments.dump()}, "m-1");
    };

    // The plan is the agent's own words, recorded under the purpose it
    // serves, and one pump takes it to a result.
    const std::string plan_action = call("setup_record", json{{"purpose", "A display bracket"},
                                                              {"headline", "Protect the visible face"},
                                                              {"decisions", json::array({json{{"topic", "orientation"},
                                                                                              {"statement", "Front face down."},
                                                                                              {"alternative", "Flat: faster, visible seam."}}})},
                                                              {"unverified", json::array({"PLA on a smooth plate"})}})
                                        .action_id;
    h.coordinator.pump();
    REQUIRE(h.coordinator.find(plan_action)->state == ToolState::Succeeded);
    const auto writes_after_plan = store.writes;
    const auto plan_result = json::parse(h.coordinator.find(plan_action)->result_json);
    CHECK(plan_result["plan"]["headline"] == "Protect the visible face");
    CHECK(plan_result["plan"]["decisions"][0]["alternative"] == "Flat: faster, visible seam.");
    CHECK(plan_result["projectUndo"] == false);
    CHECK(registry.validate_output(*registry.find("setup_record"), plan_result));

    // The activity says what the agent recorded.
    const std::string purpose_action = call("setup_record", json{{"purpose", "A display bracket for the hall"}}).action_id;
    CHECK(h.coordinator.find(purpose_action)->state == ToolState::Running);
    CHECK(h.coordinator.find(purpose_action)->title == "Record what this print is for: A display bracket for the hall");
    CHECK(store.writes == writes_after_plan); // execution has not run yet
    h.coordinator.pump();
    REQUIRE(h.coordinator.find(purpose_action)->state == ToolState::Succeeded);
    const auto purpose_result = json::parse(h.coordinator.find(purpose_action)->result_json);
    CHECK(registry.validate_output(*registry.find("setup_record"), purpose_result));
    CHECK(purpose_result["purposeAfter"] == json{{"purpose", "A display bracket for the hall"}});
    // A call with no plan keeps the one pinned before.
    CHECK(purpose_result["plan"]["headline"] == "Protect the visible face");

    // The plan is readable back through the one read, and neither call moved

