                                                                     {"quantity", 2}}})}}.dump();
        }
        events.push_back(AgentEvent::delta("I can do that."));
        events.push_back(AgentEvent::tool_call({"provider-call-1", std::move(tool), true}));
        active = true;
        return true;
    }
